      "contributions": [
        "Provides maximum-cardinality matching for sparse bipartite graphs.",
        "Supports distinguishing greedy assignment failure from slotwise infeasibility under appropriate uniqueness constraints."
      ],
      "limitations": [
        "Does not enforce arbitrary whole-sequence or cross-plan constraints.",
        "Feasibility is conditional on the supplied graph and capacity semantics."
      ]
    },
