      "title": "Understanding the Effective Receptive Field in Deep Convolutional Neural Networks",
      "link": "https://arxiv.org/abs/1701.04128",
      "contributions": [
        "Distinguishes effective influence from theoretical receptive-field extent.",
        "Motivates separating NextItNet architectural accessibility controls from measured intervention sensitivity."
      ],
      "limitations": [
        "Does not establish useful temporal dependence in this recommendation benchmark.",
        "Gradient influence alone does not identify causal user preferences."
      ]
    },
    {
      "title": "Generalized Optimal Matching Methods for Causal Inference",
      "link": "https://jmlr.csail.mit.edu/papers/v21/19-120.html",
      "contributions": [
        "Provides a framework for matching and weighting with attention to balance and overlap.",
        "Motivates explicit reporting of the population supported by successful diagnostic matches."
      ],
      "limitations": [
        "Matching model-input interventions does not supply behavioral causal identification.",
        "Broader-population conclusions require assumptions beyond successful assignments."
      ]
    },
    {
      "title": "Towards Best Practices of Activation Patching in Language Models: Metrics and Methods",
      "link": "https://arxiv.org/abs/2309.16042",
      "contributions": [
        "Studies how corruption design and output metrics affect activation-patching conclusions.",
        "Motivates a later diagnostic comparing restoration and destruction of NextItNet residual-branch activations."
      ],
      "limitations": [
        "The proposed NextItNet adaptation is unvalidated.",
        "Patching conclusions remain conditional on corruption, intervention site and metric."
      ]
    },
    {
      "title": "Sanity Checks for Saliency Maps",
      "link": "https://arxiv.org/abs/1810.03292",
      "contributions": [
        "Introduces parameter-randomization checks for attribution dependence on learned weights.",
        "Offers a control for future NextItNet influence maps."
      ],
      "limitations": [
        "Passing randomization checks does not establish attribution faithfulness.",
        "Diagnostic randomized copies must remain outside training and prediction."
      ]
    }
  ]
